PRAGMA foreign_keys=ON;
CREATE TABLE sources(source_id TEXT PRIMARY KEY,region TEXT NOT NULL,public_display_allowed INTEGER NOT NULL CHECK(public_display_allowed IN (0,1)),automated_refresh_allowed INTEGER NOT NULL CHECK(automated_refresh_allowed IN (0,1)),permission_evidence TEXT,payload_json TEXT NOT NULL);
CREATE TABLE competencies(competency_id TEXT PRIMARY KEY,name TEXT NOT NULL,dimension TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TABLE jobs(job_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources,source_record_key TEXT NOT NULL,market TEXT NOT NULL,occupation_id TEXT NOT NULL,seniority TEXT NOT NULL,posting_status TEXT NOT NULL,published_at TEXT,last_verified_at TEXT,content_hash TEXT NOT NULL,description TEXT NOT NULL,review_status TEXT NOT NULL,payload_json TEXT NOT NULL,UNIQUE(source_id,source_record_key));
CREATE INDEX jobs_market_role ON jobs(market,occupation_id,seniority);
CREATE TABLE job_versions(version_id INTEGER PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs,content_hash TEXT NOT NULL,observed_at TEXT NOT NULL,payload_json TEXT NOT NULL,UNIQUE(job_id,content_hash));
CREATE TABLE job_competencies(job_id TEXT REFERENCES jobs,competency_id TEXT REFERENCES competencies,evidence_start INTEGER NOT NULL,evidence_end INTEGER NOT NULL,payload_json TEXT NOT NULL,PRIMARY KEY(job_id,competency_id),CHECK(evidence_end>evidence_start));
CREATE TABLE occupation_profiles(profile_id TEXT PRIMARY KEY,market TEXT NOT NULL,occupation_id TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 0,payload_json TEXT NOT NULL);
CREATE TABLE occupation_transitions(edge_id TEXT PRIMARY KEY,approved INTEGER NOT NULL DEFAULT 0,payload_json TEXT NOT NULL);
CREATE TABLE ingest_runs(run_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources,started_at TEXT NOT NULL,status TEXT NOT NULL,row_count INTEGER,error TEXT);
CREATE TABLE derived_refresh_queue(job_id TEXT PRIMARY KEY REFERENCES jobs,queued_at TEXT NOT NULL,reason TEXT NOT NULL);
CREATE VIEW public_jobs AS SELECT j.* FROM jobs j JOIN sources s USING(source_id) WHERE s.public_display_allowed=1 AND s.permission_evidence IS NOT NULL AND json_extract(s.payload_json,'$.permission_reviewed_by') IS NOT NULL AND julianday(json_extract(s.payload_json,'$.permission_valid_until'))>julianday('now') AND j.review_status='approved' AND j.posting_status='active' AND j.last_verified_at IS NOT NULL AND julianday('now')-julianday(j.last_verified_at) BETWEEN 0 AND 14;
CREATE VIEW public_profiles AS SELECT p.* FROM occupation_profiles p WHERE p.approved=1 AND json_extract(p.payload_json,'$.profile_status')!='stale_requires_rebuild' AND json_array_length(p.payload_json,'$.source_job_ids')>0 AND NOT EXISTS(SELECT 1 FROM json_each(p.payload_json,'$.source_job_ids') evidence LEFT JOIN jobs j ON j.job_id=evidence.value LEFT JOIN sources s ON s.source_id=j.source_id WHERE j.job_id IS NULL OR s.public_display_allowed!=1 OR s.permission_evidence IS NULL OR json_extract(s.payload_json,'$.permission_reviewed_by') IS NULL OR COALESCE(julianday(json_extract(s.payload_json,'$.permission_valid_until')),0)<=julianday('now'));
CREATE VIEW public_transitions AS SELECT t.* FROM occupation_transitions t WHERE t.approved=1 AND NOT EXISTS(SELECT 1 FROM json_each(t.payload_json,'$.evidence_profile_ids') e LEFT JOIN public_profiles p ON p.profile_id=e.value WHERE p.profile_id IS NULL);
-- Runtime student data are deliberately empty and separate from the shared corpus.
CREATE TABLE student_profiles(student_id TEXT PRIMARY KEY,consent_version TEXT NOT NULL,created_at TEXT NOT NULL,profile_json TEXT NOT NULL,deletion_requested_at TEXT);
CREATE TABLE student_competencies(student_id TEXT REFERENCES student_profiles ON DELETE CASCADE,competency_id TEXT REFERENCES competencies,evidence_json TEXT NOT NULL,verification_status TEXT NOT NULL CHECK(verification_status IN ('unconfirmed','self_confirmed','evidence_verified')),PRIMARY KEY(student_id,competency_id));
CREATE TABLE match_results(match_id TEXT PRIMARY KEY,student_id TEXT REFERENCES student_profiles ON DELETE CASCADE,data_version TEXT NOT NULL,scoring_version TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE career_reports(report_id TEXT PRIMARY KEY,student_id TEXT REFERENCES student_profiles ON DELETE CASCADE,match_id TEXT REFERENCES match_results ON DELETE CASCADE,report_json TEXT NOT NULL,created_at TEXT NOT NULL);
